using System;
using Features.Stats;

namespace Features.Combat {
    /// <summary>
    /// Mana of a character (design doc §7.3). Max is the MaxMana stat; like Health, a bigger max
    /// adds the same amount of current mana. Regenerated by the owner (ManaRegen / s).
    /// </summary>
    public sealed class ManaPool {
        private readonly Stat _max;
        private float _lastMax;

        public float Current { get; private set; }
        public float Max => _max.Value;

        /// <summary>(current, max)</summary>
        public event Action<float, float> Changed;

        public ManaPool(Stat maxMana) {
            _max = maxMana ?? throw new ArgumentNullException(nameof(maxMana));
            _lastMax = Max;
            Current = Max;
            _max.Changed += OnMaxChanged;
        }

        public bool CanSpend(float amount) => amount <= Current + 0.0001f;

        public bool TrySpend(float amount) {
            if (amount < 0f || !CanSpend(amount)) return false;
            Current = Math.Max(0f, Current - amount);
            Changed?.Invoke(Current, Max);
            return true;
        }

        public void Restore(float amount) {
            if (amount <= 0f || Current >= Max) return;
            Current = Math.Min(Max, Current + amount);
            Changed?.Invoke(Current, Max);
        }

        public void Detach() => _max.Changed -= OnMaxChanged;

        private void OnMaxChanged(float newMax) {
            float delta = newMax - _lastMax;
            _lastMax = newMax;
            if (delta > 0f) Current += delta;
            if (Current > newMax) Current = newMax;
            Changed?.Invoke(Current, Max);
        }
    }
}
